/**
 * Shopper-language text for BRIX's storefront scripts (cart drawer, COD
 * sheet, Packs, FBT, combo pages).
 *
 * How it reaches the page:
 *   - English pages load nothing extra. Every call site carries its English:
 *     bxT('storefront.drawer.subtotal', 'Subtotal'), and that English must
 *     equal app/i18n/en.json (tests/i18n/storefront.test.mjs).
 *   - For a language BRIX has, the app embed / blocks render
 *     snippets/brix-i18n.liquid, which loads assets/brix_i18n_<lang>.js
 *     before the BRIX scripts. That file (generated by `npm run i18n:storefront`)
 *     holds createI18n() + createStorefrontI18n() + that language's
 *     storefront keys and sets window.BrixI18n.
 *   - Each script has the I18N_SHIM below (copied verbatim, or injected for
 *     server-built scripts): window.BrixI18n when it is there, else the
 *     English with {name} and simple plurals filled in.
 *
 * createStorefrontI18n() has no imports and is ES5 only: its source text is
 * written into the generated assets.
 */

// Keys the storefront files carry (error.admin.* stays admin only).
export const STOREFRONT_PREFIXES = ['storefront.', 'error.'];
export const isStorefrontKey = (key) => STOREFRONT_PREFIXES.some((p) => key.startsWith(p)) && !key.startsWith('error.admin.');

/**
 * window.BrixI18n for one language.
 * core: createI18n(). catalog: that language's storefront keys.
 *   t(key, en, vars)           the translation, else the call site's English
 *   text(saved, key, en, vars) merchant-editable text: blank or still the
 *                              English default = translated, their own words stay
 */
export function createStorefrontI18n(core, locale, catalog) {
  var cat = catalog || {};

  function own(key) { return Object.prototype.hasOwnProperty.call(cat, key); }

  function norm(s) {
    return String(s === undefined || s === null ? '' : s).replace(/\s+/g, ' ').replace(/^\s+|\s+$/g, '').toLowerCase();
  }

  function t(key, en, vars) {
    if (own(key)) {
      var text = core.formatMessage(cat[key], vars, locale);
      if (text !== null) return text;
    }
    var english = core.formatMessage(String(en === undefined || en === null ? key : en), vars, 'en');
    return english === null ? String(en) : english;
  }

  function text(saved, key, en, vars) {
    var s = norm(saved);
    if (!s || s === norm(en)) return t(key, en, vars);
    return String(saved);
  }

  return {
    locale: locale,
    dir: core.isRtl(locale) ? 'rtl' : 'ltr',
    t: t,
    text: text
  };
}

// Copied verbatim into every storefront script (checked by
// tests/i18n/storefront.test.mjs); combo-page.js gets it injected.
export const I18N_SHIM = `  /* i18n-shim:begin (copy of app/i18n/storefront.shared.js I18N_SHIM) */
  // Shopper-language text: window.BrixI18n comes from brix_i18n_<lang>.js,
  // which the app embed loads first on a page in a language BRIX has. Without
  // it the English written at the call site shows (it equals app/i18n/en.json).
  function bxFill(en, vars) {
    var v = vars || {};
    return String(en).replace(/\\{(\\w+), plural,((?:[^{}]|\\{[^{}]*\\})*)\\}/g, function (m, name, body) {
      var n = Number(v[name]);
      var pick = body.match(new RegExp('=' + n + '\\\\s*\\\\{([^{}]*)\\\\}')) || (n === 1 && body.match(/\\bone\\s*\\{([^{}]*)\\}/)) || body.match(/\\bother\\s*\\{([^{}]*)\\}/);
      return pick ? pick[1].replace(/#/g, String(n)) : '';
    }).replace(/\\{(\\w+)\\}/g, function (m, name) {
      return v[name] === undefined || v[name] === null ? '' : String(v[name]);
    });
  }
  function bxT(key, en, vars) {
    var i18n = window.BrixI18n;
    return i18n ? i18n.t(key, en, vars) : bxFill(en, vars);
  }
  // Text the merchant can edit: their own words stay; blank or still the
  // English default shows in the shopper's language.
  function bxText(saved, key, en, vars) {
    var i18n = window.BrixI18n;
    if (i18n) return i18n.text(saved, key, en, vars);
    var s = saved === undefined || saved === null ? '' : String(saved);
    return s.replace(/^\\s+|\\s+$/g, '') ? s : bxFill(en, vars);
  }
  function bxDir() {
    return window.BrixI18n && window.BrixI18n.dir === 'rtl' ? 'rtl' : 'ltr';
  }
  /* i18n-shim:end */`;
